-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.check_section_authoring(p_slug text, p_site uuid, p_scope text, p_kind text, p_html text, p_css text, p_compiled_css text, p_ast jsonb, p_slots jsonb, p_doc jsonb, p_trusted boolean, p_placement text)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner,cms_authenticated_user=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.check_section_authoring(p_slug text, p_site uuid, p_scope text, p_kind text, p_html text, p_css text, p_compiled_css text, p_ast jsonb, p_slots jsonb, p_doc jsonb, p_trusted boolean, p_placement text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE previous RECORD; field jsonb; node jsonb; header jsonb; style RECORD;
  expected_source text; expected_compiled text; expected_slots jsonb; additions text:=''; compiled_additions text:='';
  builder_css constant text:='.builder-root{padding:3rem 1.5rem;max-width:72rem;margin:auto}.builder-root h2{margin:0 0 1rem}.builder-text{line-height:1.7}.builder-image{max-width:100%;height:auto}.builder-link{display:inline-block;margin:.75rem 0}.builder-columns{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1.5rem}@media(max-width:767px){.builder-columns{grid-template-columns:1fr}}';
BEGIN
  PERFORM app.require_actor();
  IF app.is_super_admin() THEN RETURN; END IF;
  IF p_scope IS DISTINCT FROM 'site' OR p_site IS NULL OR NOT app.can_administer_site(p_site) THEN
    RAISE EXCEPTION 'only a site admin may author visual sections for this site' USING ERRCODE='CMS02';
  END IF;
  IF p_kind IS DISTINCT FROM 'structured' OR p_html IS DISTINCT FROM '' OR p_trusted IS DISTINCT FROM false
    OR p_placement IS DISTINCT FROM 'page' THEN
    RAISE EXCEPTION 'advanced source and frame definitions require a super admin; use the visual page-section builder' USING ERRCODE='CMS02';
  END IF;
  IF app.structured_section_defect('structured',p_doc,app.current_structured_schema_version()) IS NOT NULL THEN
    RAISE EXCEPTION 'the visual section structure is invalid' USING ERRCODE='CMS04';
  END IF;
  IF p_ast IS DISTINCT FROM jsonb_build_object('nodes','[]'::jsonb,'policyVersion',app.current_sanitizer_policy_version(),'cssPolicyVersion',app.current_css_policy_version()) THEN
    RAISE EXCEPTION 'visual sections cannot include compiled HTML source' USING ERRCODE='CMS02';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',value->>'name','kind',value->>'type','label',value->>'label',
    'constraints',CASE WHEN EXISTS(SELECT 1 FROM app.visual_definition_nodes(p_doc) n WHERE n->>'type'='icon' AND n->>'field'=value->>'name')
      THEN '{"presentation":"cms-line-icons-v1"}'::jsonb ELSE '{}'::jsonb END) ORDER BY ordinality),'[]'::jsonb)
    INTO expected_slots FROM jsonb_array_elements(p_doc->'fields') WITH ORDINALITY;
  IF p_slots IS DISTINCT FROM expected_slots THEN
    RAISE EXCEPTION 'visual fields must match their governed structure' USING ERRCODE='CMS02';
  END IF;
  SELECT d.placement,v.* INTO previous FROM public.section_defs d
    JOIN public.section_def_versions v ON v.section_def_id=d.id
    WHERE d.scope='site' AND d.site_id=p_site AND d.slug=p_slug ORDER BY v.version DESC LIMIT 1;
  IF previous.section_def_id IS NOT NULL AND (previous.definition_kind<>'structured' OR previous.placement<>'page') THEN
    RAISE EXCEPTION 'revising this advanced-source or frame definition requires a super admin' USING ERRCODE='CMS02';
  END IF;

  -- Existing field settings and static node properties are approved source.
  -- Visual edits may relabel/remove fields, move/remove nodes and add only the
  -- same seven block shapes the UI offers. No new attributes/embeds/repeats.
  FOR field IN SELECT value FROM jsonb_array_elements(p_doc->'fields') LOOP
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(previous.structured_doc->'fields','[]'::jsonb)) old
      WHERE old->>'name'=field->>'name' AND old-'label'=field-'label') THEN CONTINUE; END IF;
    IF (field-ARRAY['name','type','label'])<>'{}'::jsonb OR field->>'type' NOT IN ('text','richtext','image','link') THEN
      RAISE EXCEPTION 'advanced field settings require a super admin' USING ERRCODE='CMS02';
    END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(previous.structured_doc->'fields','[]'::jsonb)) old WHERE old->>'name'=field->>'name') THEN
      RAISE EXCEPTION 'existing field types and settings are preserved by visual edits' USING ERRCODE='CMS02';
    END IF;
  END LOOP;
  FOR node IN SELECT * FROM app.visual_definition_nodes(p_doc) LOOP
    header:=node-ARRAY['children','item'];
    IF EXISTS(SELECT 1 FROM app.visual_definition_nodes(previous.structured_doc) old WHERE old-ARRAY['children','item']=header) THEN CONTINUE; END IF;
    IF header IN (
      '{"type":"element","tag":"section","attributes":{"class":"builder-root"}}'::jsonb,
      '{"type":"element","tag":"h2"}'::jsonb,
      '{"type":"element","tag":"div"}'::jsonb,
      '{"type":"element","tag":"div","attributes":{"class":"builder-text"}}'::jsonb,
      '{"type":"element","tag":"div","attributes":{"class":"builder-group"}}'::jsonb,
      '{"type":"element","tag":"div","attributes":{"class":"builder-columns"}}'::jsonb
    ) OR (header-'field') IN (
      '{"type":"text"}'::jsonb,'{"type":"richtext"}'::jsonb,'{"type":"icon"}'::jsonb,
      '{"type":"image","staticAttributes":{"class":["builder-image"],"loading":"lazy","decoding":"async"}}'::jsonb,
      '{"type":"link","staticAttributes":{"class":["builder-link"]}}'::jsonb
    ) THEN CONTINUE; END IF;
    RAISE EXCEPTION 'new advanced node properties require a super admin' USING ERRCODE='CMS02';
  END LOOP;

  IF previous.section_def_id IS NULL THEN
    expected_source:=builder_css;
    expected_compiled:=app.visual_builder_compiled_css(p_slug,builder_css);
  ELSE
    expected_source:=previous.source_css; expected_compiled:=previous.compiled_css;
    FOR style IN SELECT * FROM app.visual_builder_styles() LOOP
      IF position('.'||style.name IN expected_source)=0 AND EXISTS(
        SELECT 1 FROM app.visual_definition_nodes(p_doc) AS item(value) WHERE
          (item.value->>'type'='element' AND style.name=ANY(regexp_split_to_array(COALESCE(item.value#>>'{attributes,class}',''),'\s+')))
          OR (item.value->>'type' IN ('image','link') AND COALESCE(item.value#>'{staticAttributes,class}','[]'::jsonb) ? style.name)
      ) THEN
        additions:=additions||style.source;
        compiled_additions:=compiled_additions||app.visual_builder_compiled_css(p_slug,style.source);
      END IF;
    END LOOP;
    IF additions<>'' THEN expected_source:=expected_source||E'\n'||additions; expected_compiled:=expected_compiled||compiled_additions; END IF;
  END IF;
  IF p_css IS DISTINCT FROM expected_source OR p_compiled_css IS DISTINCT FROM expected_compiled THEN
    RAISE EXCEPTION 'visual edits preserve approved styling; changing CSS source requires a super admin' USING ERRCODE='CMS02';
  END IF;
END $function$
